import time


class TokenBucket:
    """A token bucket rate limiter. See TASK.md."""

    def __init__(self, rate, capacity, clock=time.monotonic):
        if rate <= 0 or capacity <= 0:
            raise ValueError("rate and capacity must be greater than zero")
        self.rate = rate
        self.capacity = capacity
        self.clock = clock
        self._tokens = capacity
        self._last = clock()

    def _update(self):
        current = self.clock()
        if current > self._last:
            self._tokens = min(
                self.capacity,
                self._tokens + self.rate * (current - self._last),
            )
            self._last = current

    def _validate_cost(self, cost):
        if cost <= 0 or cost > self.capacity:
            raise ValueError("cost must be greater than zero and at most capacity")

    def take(self, cost=1):
        self._validate_cost(cost)
        self._update()
        if self._tokens >= cost:
            self._tokens -= cost
            return True
        return False

    def available(self):
        self._update()
        return self._tokens

    def wait_time(self, cost=1):
        self._validate_cost(cost)
        self._update()
        if self._tokens >= cost:
            return 0
        return (cost - self._tokens) / self.rate
